 records.append({'source_index':f,'source_frame':f,'representative_frame':s,'path':f'tactical-native-frames/frame-{f:03}.png','output_path':f'tactical-native-frames/frame-{f:03}.png','kind':'exact_full_canvas_source_mirror','proof':'native-reference/source-record.json'})
